{
  "format": "kentos.data-profile",
  "version": 1,
  "name": "park-bahce",
  "title": "Park ve bahçeler profili",
  "description": "Ağaçlar ve yeşil alanlar; üç sürüm.",
  "basis": "Kurumun kendi çalışma profili; resmî bir şema değildir.",
  "release": 3,
  "migrations": [
    {
      "from": 1,
      "to": 2,
      "title": "Ağaç katmanı yeni adlarıyla",
      "steps": [
        {
          "kind": "renameLayer",
          "layer": [
            "Peyzaj",
            "Ağaçlar"
          ],
          "to": "Ağaç"
        },
        {
          "kind": "renameField",
          "layer": [
            "Peyzaj",
            "Ağaç"
          ],
          "from": "No",
          "to": "AgacNo"
        },
        {
          "kind": "renameField",
          "layer": [
            "Peyzaj",
            "Ağaç"
          ],
          "from": "Alan",
          "to": "YesilAlan"
        },
        {
          "kind": "changeFieldType",
          "layer": [
            "Peyzaj",
            "Ağaç"
          ],
          "field": {
            "name": "Yas",
            "alias": "Yaş",
            "kind": "integer",
            "min": "0",
            "max": "500"
          },
          "onFail": "keep"
        }
      ]
    },
    {
      "from": 2,
      "to": 3,
      "title": "Türler ve sulama listeleri; yeşil alan türleri",
      "steps": [
        {
          "kind": "changeFieldType",
          "layer": [
            "Peyzaj",
            "Ağaç"
          ],
          "field": {
            "name": "Tur",
            "alias": "Tür",
            "kind": "text",
            "domain": "agac-tur"
          },
          "onFail": "keep"
        },
        {
          "kind": "retireCode",
          "domain": "agac-tur",
          "code": "palmiye",
          "replaceWith": "diger"
        },
        {
          "kind": "changeFieldType",
          "layer": [
            "Peyzaj",
            "Ağaç"
          ],
          "field": {
            "name": "Sulama",
            "kind": "text",
            "domain": "sulama"
          },
          "onFail": "clear"
        },
        {
          "kind": "mapValues",
          "layer": [
            "Peyzaj",
            "Yeşil alan"
          ],
          "field": "Tip",
          "map": [
            {
              "from": "Bitki",
              "to": "orman-bitkisi",
              "whenField": "Bolge",
              "whenEquals": "orman"
            },
            {
              "from": "Bitki",
              "to": "bahce-bitkisi",
              "whenField": "Bolge",
              "whenEquals": "bahce"
            },
            {
              "from": "Bitki",
              "to": "bitki"
            }
          ]
        }
      ]
    }
  ],
  "domains": [
    {
      "id": "agac-tur",
      "name": "Ağaç türü",
      "kind": "text",
      "values": [
        {
          "code": "cinar",
